def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    n_cells = 2574
    in_cells = [False] * n_cells
    state = [0] * n_cells
    cell_val: list[int | str] = [0] * n_cells
    cell_ast: list[object] = [None] * n_cells
    name_to_idx: dict[str, int] = {}

    for name in cells:
        idx = (int(name[1:]) - 1) * 26 + (ord(name[0]) - 65)
        name_to_idx[name] = idx
        in_cells[idx] = True

    def tokenize(s: str) -> list[tuple[str, object]]:
        tokens: list[tuple[str, object]] = []
        i = 0
        length = len(s)
        while i < length:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif '0' <= ch <= '9':
                j = i + 1
                while j < length and '0' <= s[j] <= '9':
                    j += 1
                tokens.append(('NUM', int(s[i:j])))
                i = j
            elif 'A' <= ch <= 'Z':
                j = i + 1
                while j < length and ('A' <= s[j] <= 'Z' or '0' <= s[j] <= '9'):
                    j += 1
                word = s[i:j]
                if word in ('SUM', 'MIN', 'MAX', 'IF'):
                    tokens.append(('FUNC', word))
                else:
                    c_idx = (int(word[1:]) - 1) * 26 + (ord(word[0]) - 65)
                    tokens.append(('CELL', c_idx))
                i = j
            elif ch == '<':
                if i + 1 < length and s[i + 1] == '>':
                    tokens.append(('OP', '<>'))
                    i += 2
                elif i + 1 < length and s[i + 1] == '=':
                    tokens.append(('OP', '<='))
                    i += 2
                else:
                    tokens.append(('OP', '<'))
                    i += 1
            elif ch == '>':
                if i + 1 < length and s[i + 1] == '=':
                    tokens.append(('OP', '>='))
                    i += 2
                else:
                    tokens.append(('OP', '>'))
                    i += 1
            elif ch == '=':
                tokens.append(('OP', '='))
                i += 1
            else:
                tokens.append((ch, ch))
                i += 1
        return tokens

    def parse(tokens: list[tuple[str, object]]) -> object:
        pos = 0
        n = len(tokens)

        def parse_expr() -> object:
            nonlocal pos
            node = parse_term()
            while pos < n and tokens[pos][0] in ('+', '-'):
                op = tokens[pos][0]
                pos += 1
                right = parse_term()
                node = ('BINOP', op, node, right)
            return node

        def parse_term() -> object:
            nonlocal pos
            node = parse_unary()
            while pos < n and tokens[pos][0] in ('*', '/'):
                op = tokens[pos][0]
                pos += 1
                right = parse_unary()
                node = ('BINOP', op, node, right)
            return node

        def parse_unary() -> object:
            nonlocal pos
            neg_count = 0
            while pos < n and tokens[pos][0] == '-':
                neg_count += 1
                pos += 1
            node = parse_atom()
            if neg_count & 1:
                node = ('NEG', node)
            return node

        def parse_atom() -> object:
            nonlocal pos
            tok_type, tok_val = tokens[pos]
            if tok_type == 'NUM':
                pos += 1
                return ('NUM', tok_val)
            if tok_type == 'CELL':
                pos += 1
                return ('CELL', tok_val)
            if tok_type == '(':
                pos += 1
                node = parse_expr()
                pos += 1  # ')'
                return node
            # tok_type == 'FUNC'
            pos += 2  # func name and '('
            if tok_val == 'IF':
                left = parse_expr()
                op = tokens[pos][1]
                pos += 1
                right = parse_expr()
                pos += 1  # ','
                then_expr = parse_expr()
                pos += 1  # ','
                else_expr = parse_expr()
                pos += 1  # ')'
                return ('IF', op, left, right, then_expr, else_expr)

            items: list[object] = []
            while True:
                if (
                    tokens[pos][0] == 'CELL'
                    and pos + 1 < n
                    and tokens[pos + 1][0] == ':'
                ):
                    idx1: int = tokens[pos][1]  # type: ignore[assignment]
                    idx2: int = tokens[pos + 2][1]  # type: ignore[assignment]
                    pos += 3
                    r1, c1 = divmod(idx1, 26)
                    r2, c2 = divmod(idx2, 26)
                    r_lo, r_hi = (r1, r2) if r1 <= r2 else (r2, r1)
                    c_lo, c_hi = (c1, c2) if c1 <= c2 else (c2, c1)
                    for r in range(r_lo, r_hi + 1):
                        base = r * 26
                        for c in range(c_lo, c_hi + 1):
                            c_idx = base + c
                            if in_cells[c_idx]:
                                items.append(('CELL', c_idx))
                else:
                    items.append(parse_expr())
                if tokens[pos][0] == ',':
                    pos += 1
                else:
                    pos += 1  # ')'
                    break
            return ('AGG', tok_val, items)

        return parse_expr()

    for name, content in cells.items():
        idx = name_to_idx[name]
        stripped = content.lstrip()
        if stripped.startswith('='):
            cell_ast[idx] = parse(tokenize(stripped[1:]))
        else:
            state[idx] = 2
            cell_val[idx] = int(content)

    for start_idx in name_to_idx.values():
        if state[start_idx] == 2:
            continue
        state[start_idx] = 1
        stack: list[tuple[object, ...]] = [('CELL_DONE', start_idx)]
        node: object = cell_ast[start_idx]
        dispatching = True
        val: int | str = 0

        while True:
            if dispatching:
                kind = node[0]  # type: ignore[index]
                if kind == 'NUM':
                    val = node[1]  # type: ignore[index]
                    dispatching = False
                elif kind == 'CELL':
                    c_idx = node[1]  # type: ignore[index]
                    if not in_cells[c_idx]:
                        val = 0
                        dispatching = False
                    elif state[c_idx] == 2:
                        val = cell_val[c_idx]
                        dispatching = False
                    elif state[c_idx] == 1:
                        val = '#CYCLE!'
                        dispatching = False
                    else:
                        state[c_idx] = 1
                        stack.append(('CELL_DONE', c_idx))
                        node = cell_ast[c_idx]
                elif kind == 'NEG':
                    stack.append(('NEG_DONE',))
                    node = node[1]  # type: ignore[index]
                elif kind == 'BINOP':
                    stack.append(('BINOP_L', node[1], node[3]))  # type: ignore[index]
                    node = node[2]  # type: ignore[index]
                elif kind == 'AGG':
                    items = node[2]  # type: ignore[index]
                    if not items:
                        val = 0
                        dispatching = False
                    else:
                        stack.append(('AGG_STEP', node[1], items, 0, None))  # type: ignore[index]
                        node = items[0]
                else:  # 'IF'
                    stack.append(('IF_L', node[1], node[3], node[4], node[5]))  # type: ignore[index]
                    node = node[2]  # type: ignore[index]
            else:
                if not stack:
                    break
                frame = stack.pop()
                fkind = frame[0]
                if fkind == 'CELL_DONE':
                    c_idx = frame[1]  # type: ignore[assignment]
                    state[c_idx] = 2
                    cell_val[c_idx] = val
                elif fkind == 'NEG_DONE':
                    if not isinstance(val, str):
                        val = -val
                elif fkind == 'BINOP_L':
                    if not isinstance(val, str):
                        stack.append(('BINOP_R', frame[1], val))
                        node = frame[2]
                        dispatching = True
                elif fkind == 'BINOP_R':
                    if not isinstance(val, str):
                        op = frame[1]
                        left_val: int = frame[2]  # type: ignore[assignment]
                        if op == '+':
                            val = left_val + val
                        elif op == '-':
                            val = left_val - val
                        elif op == '*':
                            val = left_val * val
                        else:  # '/'
                            if val == 0:
                                val = '#DIV/0!'
                            else:
                                q = abs(left_val) // abs(val)
                                if (left_val < 0) ^ (val < 0):
                                    q = -q
                                val = q
                elif fkind == 'AGG_STEP':
                    if not isinstance(val, str):
                        func = frame[1]
                        items = frame[2]
                        i_pos: int = frame[3]  # type: ignore[assignment]
                        acc = frame[4]
                        if acc is None:
                            acc = val
                        elif func == 'SUM':
                            acc += val
                        elif func == 'MIN':
                            if val < acc:
                                acc = val
                        else:  # 'MAX'
                            if val > acc:
                                acc = val
                        i_pos += 1
                        if i_pos == len(items):  # type: ignore[arg-type]
                            val = acc
                        else:
                            stack.append(('AGG_STEP', func, items, i_pos, acc))
                            node = items[i_pos]  # type: ignore[index]
                            dispatching = True
                elif fkind == 'IF_L':
                    if not isinstance(val, str):
                        stack.append(('IF_R', frame[1], val, frame[3], frame[4]))
                        node = frame[2]
                        dispatching = True
                else:  # 'IF_R'
                    if not isinstance(val, str):
                        op = frame[1]
                        left_val = frame[2]  # type: ignore[assignment]
                        if op == '=':
                            cond = left_val == val
                        elif op == '<>':
                            cond = left_val != val
                        elif op == '<':
                            cond = left_val < val
                        elif op == '<=':
                            cond = left_val <= val
                        elif op == '>':
                            cond = left_val > val
                        else:  # '>='
                            cond = left_val >= val
                        node = frame[3] if cond else frame[4]
                        dispatching = True

    return {name: cell_val[idx] for name, idx in name_to_idx.items()}
